  function openInspection(){ openDialog('\uc810\uac80 \ub4f1\ub85d',`<form data-inspection-form><label>\uc124\ube44<select name="equipmentId" required>${state.equipment.map(x=>`<option value="${x.id}">${x.id}</option>`).join('')}</select></label><label>\uc810\uac80 \uba54\ubaa8<textarea name="note" required placeholder="\uc810\uac80 \ub0b4\uc6a9\uc744 \uc785\ub825\ud558\uc138\uc694."></textarea></label><div class="dialog-actions"><button type="button" class="button secondary" data-action="close-dialog">\ucde8\uc18c</button><button class="button primary">\uc800\uc7a5</button></div></form>`); }
  function reset(){ state=freshState(); saveState(); showView('dashboard'); toast('\uc0d8\ud50c \ub370\uc774\ud130\ub97c \ucd08\uae30\ud654\ud588\uc2b5\ub2c8\ub2e4.'); }
  document.addEventListener('click',(event)=>{ const target=event.target; const nav=target.closest('[data-view]'); if(nav){showView(nav.dataset.view);return;} const equipment=target.closest('[data-equipment-id]'); if(equipment){openEquipment(equipment.dataset.equipmentId);return;} const map=target.closest('[data-map-id]'); if(map){state.selectedMapId=map.dataset.mapId;renderMap();return;} const mapFilter=target.closest('[data-map-filter]'); if(mapFilter){state.mapFilter=mapFilter.dataset.mapFilter;renderMap();return;} const alertFilter=target.closest('[data-alert-filter]'); if(alertFilter){$('[data-alert-filters]').dataset.filter=alertFilter.dataset.alertFilter;renderAlerts();return;} const detail=target.closest('[data-alert-detail]'); if(detail){const row=state.alerts.find(x=>x.id===detail.dataset.alertDetail);if(row)openDialog('\uc54c\ub9bc \uc0c1\uc138',`<div class="detail-list"><div><span>\uc124\ube44</span><strong>${row.equipmentId}</strong></div><div><span>\ub4f1\uae09</span><strong>${row.severity}</strong></div><div><span>\ub0b4\uc6a9</span><strong>${row.message}</strong></div></div>`);return;} const ack=target.closest('[data-alert-ack]'); if(ack){const row=state.alerts.find(x=>x.id===ack.dataset.alertAck);if(row){row.acknowledgedAt=new Date().toISOString();saveState();render();toast('\uc54c\ub9bc\uc744 \ud655\uc778 \ucc98\ub9ac\ud588\uc2b5\ub2c8\ub2e4.');}return;} const monitor=target.closest('[data-spare-monitor-key]'); if(monitor){ const key=monitor.dataset.spareMonitorKey; const current=state.spareMonitor?.[key]??0; const next=prompt('\uc218\ub7c9\uc744 \uc785\ub825\ud558\uc138\uc694.',String(current)); if(next!==null&&/^\d+$/.test(next)){state.spareMonitor={...state.spareMonitor,[key]:Number(next)};saveState();renderSpareMonitor();} return;} const materialEdit=target.closest('[data-material-edit]'); if(materialEdit){openMaterialForm(materialEdit.dataset.materialEdit);return;} const materialDelete=target.closest('[data-material-delete]'); if(materialDelete){state.materials=state.materials.filter(row=>row.id!==materialDelete.dataset.materialDelete);saveState();render();return;} const spareEdit=target.closest('[data-spare-edit]'); if(spareEdit){openSpareForm(spareEdit.dataset.spareEdit);return;} const spareDelete=target.closest('[data-spare-delete]'); if(spareDelete){state.spares=state.spares.filter(row=>row.id!==spareDelete.dataset.spareDelete);saveState();render();return;} const action=target.closest('[data-action]')?.dataset.action; if(action==='csv-upload'){$('[data-csv-upload]').click();return;} if(action==='material-csv'){$('[data-material-upload]').click();return;} if(action==='spare-csv'){$('[data-spare-upload]').click();return;} if(action==='new-material'){openMaterialForm();return;} if(action==='new-spare'){openSpareForm();return;} if(action==='close-dialog'){$('[data-dialog]').close();return;} if(action==='prep'){state.prepStarted=true;saveState();toast('\uc900\ube44 \ubaa8\ub4dc\uac00 \uc2dc\uc791\ub418\uc5c8\uc2b5\ub2c8\ub2e4.');target.disabled=true;target.textContent='\uc900\ube44 \ubaa8\ub4dc \uc2e4\ud589 \uc911';return;} if(action==='inspection'){openInspection();return;} if(action==='reset'){if(confirm('\uc0d8\ud50c \ub370\uc774\ud130\ub85c \ucd08\uae30\ud654\ud560\uae4c\uc694?'))reset();return;} if(action==='notifications'){showView('alerts');return;} if(action==='settings'){toast('\uc124\uc815 \uae30\ub2a5\uc740 \ub370\ubaa8\uc5d0\uc11c \uc81c\uacf5\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.');return;} });
  document.addEventListener('submit',(event)=>{ if(!event.target.matches('[data-inspection-form]'))return; event.preventDefault(); const data=new FormData(event.target); const note=String(data.get('note')||'').trim(); if(!note){toast('\uc810\uac80 \uba54\ubaa8\ub97c \uc785\ub825\ud558\uc138\uc694.',true);return;} state.inspections.push({id:`inspection-${Date.now()}`,equipmentId:data.get('equipmentId'),note,createdAt:new Date().toISOString()});saveState();$('[data-dialog]').close();render();toast('\uc810\uac80\uc774 \ub4f1\ub85d\ub418\uc5c8\uc2b5\ub2c8\ub2e4.'); });
  document.addEventListener('change',(event)=>{ if(!event.target.matches('[data-csv-upload]')) return; const file=event.target.files?.[0]; if(!file) return; const reader=new FileReader(); reader.onload=()=>{ const updates=parseEquipmentCsv(String(reader.result||'')); let count=0; updates.forEach(update=>{ const existing=state.equipment.find(item=>item.id===update.id); if(existing){Object.assign(existing,update);count++;} }); if(count){saveState();render();toast(`${count}\uac1c \uc124\ube44 \ub370\uc774\ud130\uac00 \uc5c5\ub370\uc774\ud2b8\ub418\uc5c8\uc2b5\ub2c8\ub2e4.`);} else toast('\uc5c5\ub370\uc774\ud2b8\ud560 \uc124\ube44 \ub370\uc774\ud130\ub97c \ucc3e\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.',true); event.target.value=''; }; reader.readAsText(file,'UTF-8'); });
  $('[data-dialog]').addEventListener('click',(event)=>{ if(event.target === $('[data-dialog]')) $('[data-dialog]').close(); });
  render();
  void hydrateFromSupabase();

document.addEventListener('submit',async (event)=>{ if(event.target.matches('[data-material-form]')){ event.preventDefault(); const data=new FormData(event.target); const name=String(data.get('name')||'').trim(); const quantity=Number(data.get('quantity')); if(!name||!Number.isFinite(quantity)){toast('\uc790\uc7ac\uba85\uacfc \uc218\ub7c9\uc744 \uc785\ub825\ud558\uc138\uc694.',true);return;} const id=event.target.dataset.id; const row={name,quantity,dueDate:String(data.get('dueDate')||''),status:String(data.get('status')||'purchasing')}; const existing=state.materials.find(item=>item.id===id); if(existing) Object.assign(existing,row); else state.materials.push({id:`material-${Date.now()}`,...row}); const saved=await saveState(); if(!saved)return; $('[data-dialog]').close(); render(); toast('\uc790\uc7ac\ub97c \uc800\uc7a5\ud588\uc2b5\ub2c8\ub2e4.'); return; } if(event.target.matches('[data-spare-form]')){ event.preventDefault(); const data=new FormData(event.target); const name=String(data.get('name')||'').trim(); const quantity=Number(data.get('quantity')); if(!name||!Number.isFinite(quantity)){toast('\uc608\ube44\ud488\uba85\uacfc \uc218\ub7c9\uc744 \uc785\ub825\ud558\uc138\uc694.',true);return;} const id=event.target.dataset.id; const row={name,quantity,repairStatus:String(data.get('repairStatus')||'\uc218\ub9ac \ud544\uc694'),startDate:String(data.get('startDate')||''),completedDate:String(data.get('completedDate')||''),memo:String(data.get('memo')||'').trim()}; const existing=state.spares.find(item=>item.id===id); if(existing) Object.assign(existing,row); else state.spares.push({id:`spare-${Date.now()}`,...row}); const saved=await saveState(); if(!saved)return; $('[data-dialog]').close(); render(); toast('\uc608\ube44\ud488\uc744 \uc800\uc7a5\ud588\uc2b5\ub2c8\ub2e4.'); return; } });
  document.addEventListener('change',(event)=>{ if(event.target.matches('[data-csv-upload]')) recordNextEquipmentHistory=true; },true);
  document.addEventListener('click',(event)=>{ const card=event.target.closest('[data-material-monitor-key]'); if(!card) return; const key=card.dataset.materialMonitorKey; const current=state.materialMonitor?.[key]??0; const next=prompt('\uc7ac\uace0 \uc218\ub7c9\uc744 \uc785\ub825\ud558\uc138\uc694.',String(current)); if(next!==null&&/^\d+$/.test(next)){state.materialMonitor={...state.materialMonitor,[key]:Number(next)};saveState();renderMaterialMonitor();toast('\uc790\uc7ac \uc7ac\uace0\ub97c \uc800\uc7a5\ud588\uc2b5\ub2c8\ub2e4.');} });
